#!/usr/bin/env sh
# Creates deploy/.env with fresh random secrets the first time, so `make up` works on a clean clone
# and no password is ever committed. An existing file is left alone.
set -eu

file="${1:-deploy/.env}"
if [ -f "$file" ]; then
  exit 0
fi

secret() { od -An -N24 -tx1 /dev/urandom | tr -d ' \n'; }

umask 077
cat >"$file" <<EOF
# Local secrets for deploy/compose.yaml. Generated by tools/scripts/dev-env.sh; never commit this file.
POSTGRES_PASSWORD=$(secret)
CLICKHOUSE_PASSWORD=$(secret)
REDIS_PASSWORD=$(secret)
S3_ACCESS_KEY=voicegateway
S3_SECRET_KEY=$(secret)
EOF
echo "created $file with random secrets"
